Your expense tracker is ready below. Add each spend with an amount and category, and it keeps a running total for the month. Entries last only while this page is open.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:16px;background:#faf7f2;color:#222}
h1{font-size:18px;margin:0 0 12px}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:90px}
button{background:#d9534f;color:#fff;border:0;cursor:pointer}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
.total{font-size:24px;font-weight:600}
.bar{height:8px;background:#eee;border-radius:4px;overflow:hidden;margin:4px 0 10px}
.bar i{display:block;height:100%;background:#d9534f}
.cat{display:flex;justify-content:space-between;font-size:13px}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
.item small{color:#777}
.x{background:none;color:#999;padding:2px 8px;font-size:16px}
.over{color:#c0392b}
</style></head><body>
<h1>Monthly expenses</h1>
<div class="card">
  <div class="row">
    <input id="d" placeholder="What was it?">
    <input id="a" type="number" min="0" placeholder="Amount (₹)">
    <select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option></select>
    <button id="add">Add</button>
  </div>
  <div class="row" style="margin:0">
    <input id="b" type="number" min="0" placeholder="Monthly budget (₹), optional">
  </div>
</div>
<div class="card">
  <div>Total this month</div>
  <div class="total" id="t">₹0</div>
  <div id="bl" style="font-size:13px"></div>
</div>
<div class="card"><div id="cats">No spends yet.</div></div>
<div class="card"><div id="list">Nothing added yet.</div></div>
<script>
var items=[],budget=0;
var fmt=function(n){return '₹'+Number(n).toLocaleString('en-IN')};
function esc(s){return s.replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function render(){
  var tot=0,by={};
  items.forEach(function(i){tot+=i.a;by[i.c]=(by[i.c]||0)+i.a});
  document.getElementById('t').textContent=fmt(tot);
  var bl=document.getElementById('bl');
  if(budget>0){
    var left=budget-tot;
    bl.innerHTML=left>=0?'Left of budget: '+fmt(left):'<span class="over">Over budget by '+fmt(-left)+'</span>';
  }else bl.textContent='';
  var ck=Object.keys(by).sort(function(x,y){return by[y]-by[x]});
  document.getElementById('cats').innerHTML=ck.length?ck.map(function(k){
    var p=Math.round(by[k]/tot*100);
    return '<div class="cat"><span>'+k+'</span><span>'+fmt(by[k])+' ('+p+'%)</span></div><div class="bar"><i style="width:'+p+'%"></i></div>';
  }).join(''):'No spends yet.';
  document.getElementById('list').innerHTML=items.length?items.map(function(i,n){
    return '<div class="item"><span>'+esc(i.d)+'<br><small>'+i.c+'</small></span><span>'+fmt(i.a)+' <button class="x" data-n="'+n+'">×</button></span></div>';
  }).join(''):'Nothing added yet.';
}
document.getElementById('add').onclick=function(){
  var a=parseFloat(document.getElementById('a').value);
  if(!(a>0))return;
  items.unshift({d:document.getElementById('d').value||'Expense',a:a,c:document.getElementById('c').value});
  document.getElementById('d').value='';document.getElementById('a').value='';
  render();
};
document.getElementById('b').oninput=function(){budget=parseFloat(this.value)||0;render()};
document.getElementById('list').onclick=function(e){
  var n=e.target.getAttribute('data-n');
  if(n!==null){items.splice(+n,1);render()}
};
render();
</script></body></html>
```
